ValidationRule.errorConditionFormula:
AND(
    /* 1. Only target MBG sub-type cases */
    ISPICKVAL(Sub_Type_1__c, "MBG"),

    /* 2. Triggers when the Claim Stage is set to Decision Pending */
    ISPICKVAL(Claim_Stage__c, "Decision Pending"),

    /* 3. Throws the error if the checklist is blank/false */
    NOT(MBG_Checklist__c)
)
